  +
  +export function getAuthorizationCodeOAuthProviderIds(): AuthorizationCodeOAuthProviderId[] {
  +	return Object.keys(AUTHORIZATION_CODE_OAUTH_PROVIDERS) as AuthorizationCodeOAuthProviderId[];
